SELECT c.customer_id, c.first_name, c.last_name, c.email
FROM customers AS c
WHERE NOT EXISTS (
    SELECT 1 FROM orders AS o WHERE o.customer_id = c.customer_id
)
ORDER BY c.customer_id;

SELECT c.customer_id, c.first_name, c.last_name, c.email
FROM customers AS c
WHERE NOT EXISTS (
    SELECT 1 FROM orders AS o WHERE o.customer_id = c.customer_id
)
ORDER BY c.customer_id;

SELECT p.product_id, p.name, p.sku
FROM products AS p
WHERE NOT EXISTS (
    SELECT 1 FROM order_items AS oi WHERE oi.product_id = p.product_id
)
ORDER BY p.product_id;

SELECT p.product_id, p.name AS product_name, cat.name AS category_name
FROM products AS p
JOIN categories AS cat ON cat.category_id = p.category_id
WHERE p.product_id IN (
    SELECT oi.product_id FROM order_items AS oi WHERE oi.order_id = 2500
);

SELECT p.sku, p.price AS current_list_price
FROM products AS p
WHERE p.sku = 'SKU-00042';

WITH consent_status AS (
  SELECT c.customer_id, CASE WHEN c.marketing_opt_in IS NULL THEN 1 ELSE 0 END AS never_asked
  FROM customers AS c
)
SELECT sum(cs.never_asked) AS never_asked_count
FROM consent_status AS cs;

WITH orders_2025 AS (
  SELECT o.order_id
  FROM orders AS o
  WHERE o.order_date >= DATE '2025-01-01' AND o.order_date < DATE '2026-01-01'
)
SELECT count(*) AS order_count FROM orders_2025;

