WITH refund_totals AS (
  SELECT r.refund_id, r.amount
  FROM refunds AS r
)
SELECT sum(rt.amount) AS total_refunded
FROM refund_totals AS rt;

SELECT count(*) AS orders_with_refund
FROM orders AS o
WHERE EXISTS (
    SELECT 1 FROM refunds AS r WHERE r.order_id = o.order_id
);
